ewlabel{sec:within_pool}{{4.3}{6}{Within-pool controlled comparison}{section*.17}{}}

ewlabel{sec:practical_magnitude}{{4.3}{6}{Practical magnitude}{section*.18}{}}

ewlabel{fig:error_taxonomy}{{2}{7}{Error taxonomy decomposition (Few-NERD NER and FewRel RE). IntraSub scales monotonically with BCS across all evaluated datasets ($ho = 0.84	ext {--}1.0$; Table~ef {tab:error_taxonomy} includes DocRED). RE missed rates remain flat (10--16\%), but NER missed rates are substantially higher (43--65\%) and non-monotonic}{figure.caption.15}{}}

ewlabel{sec:multi_channel}{{4.4}{7}{Multi-Dimensional Degradation}{subsection.4.4}{}}

ewlabel{sec:centrality_confound}{{4.5}{8}{Centrality as a Potential Confound on Homogeneous Schemas}{subsection.4.5}{}}

