ewlabel{sec:appendix_sdgd}{{B}{12}{SDGD Full Protocol and Results}{appendix.B}{}}

ewlabel{tab:cross_model}{{3}{12}{Cross-model count-curve replication on Few-NERD (text-match recall). Both models show a general declining trend in recall with schema size. Per-batch correlation $r = 0.725$. Qwen3-32B values use the v2 prompt (\S ef {sec:model}) for fair cross-model comparison; the count-curve results in \S ef {sec:count_curves} use the v1 prompt, yielding higher absolute recall (0.72 vs.\ 0.64 at count${}\,=\,1$) due to over-prediction under v1}{table.caption.25}{}}

ewlabel{tab:cross_model_bcs}{{4}{12}{Cross-model BCS-controlled FewRel accuracy. High-BCS accuracy converges to $\approx $51\% regardless of model, while low-BCS accuracy reflects model capacity differences. The confusability gap ($\Delta $, in pp) is 77--87\% as large on Llama-3.1-8B as on Qwen3-32B}{table.caption.26}{}}

ewlabel{tab:cross_model_ner_null}{{5}{13}{NER batch-level BCS--F1 correlation across models. $^\dagger $Partial correlation controlling for type frequency. $^\ddagger $LLaMA-70B count\_12 shows $r{=}{-}0.42$ ($p{=}0.034$, uncorrected; Bonferroni $p{=}0.069$); pooled and count\_6 are null, consistent with sampling noise at $n{=}25$. The null is observed on three models; Gemini remains untested}{table.caption.27}{}}

ewlabel{tab:error_taxonomy}{{6}{13}{Intra-batch substitution (IntraSub) and missed-entity rates by BCS bin. Spearman $ho $ computed over $n=148$ batches (NER), $n=154$ (RE), and $n=110$ (DocRE). IntraSub scales monotonically with BCS across all three datasets. DocRE missed rates decrease with BCS, indicating high-confusability errors shift from omission to substitution}{table.caption.28}{}}

ewlabel{tab:cross_model_error_taxonomy}{{7}{13}{Cross-model replication of IntraSub--BCS Spearman correlation on FewRel RE. $^\dagger $LLaMA-70B has only 20 batches with 17.4\% missed rate; the null is attributable to insufficient power rather than absence of the effect}{table.caption.29}{}}

ewlabel{tab:sdgd_results}{{8}{13}{Few-NERD extraction under decomposition modes. V1 uses union merge; v2 uses confidence-gated merge with 	exttt {min\_batch\_size=8} (reducing 8$	o $4 batches for sdgd\_zero). All decomposition modes produce lower F1 than the single-pass baseline. All modes use the v1 prompt}{table.caption.30}{}}

ewlabel{sec:appendix_routing}{{B.1}{13}{Practical Routing Strategies on RE}{subsection.B.1}{}}

ewlabel{tab:routing_strategies}{{9}{13}{Routing strategy comparison on FewRel 80-relation RE with graph-coloring sub-schema decomposition. Oracle requires gold labels. All practical (non-oracle) strategies perform below the single-pass baseline. The failure stems from constrained decoding (enum constraint), which forces confident predictions in every sub-schema: 73.4\% of instances receive positive predictions from 3--5 sub-schemas simultaneously, with per-sub-schema none-rates of only 20--40\%}{table.caption.31}{}}

ewlabel{sec:appendix_factorial}{{C}{14}{Factorial Analysis and Separability Test}{appendix.C}{}}

ewlabel{tab:tost_sensitivity}{{10}{14}{TOST sensitivity analysis across equivalence margins. The interaction effect (0.47\,pp, 90\% CI [$-$1.0, 2.0]\,pp) is bounded below 2\,pp at marginal significance ($p = 0.047$); the $\pm 3$\,pp choice does not drive the equivalence conclusion. At $\pm 1$\,pp, equivalence is inconclusive ($p = 0.278$), meaning interaction could reach approximately half the main effect magnitude}{table.caption.33}{}}

ewlabel{sec:appendix_within_pool}{{D}{15}{Within-Pool CI Details}{appendix.D}{}}

ewlabel{sec:appendix_residualized_bcs}{{E}{15}{Controlling for Centrality Confounds in MAVEN Per-Type Analysis}{appendix.E}{}}

ewlabel{tab:residualized_bcs}{{11}{15}{MAVEN per-type BCS--F1 correlation before and after controlling for centrality confounders. Raw correlations are Spearman $ho $; partial correlations are Pearson $r$ from residualized regression. Degree centrality is computed on the SCS graph at threshold 0.7. All values from experiment 	exttt {exp\_maven\_residualized\_bcs}}{table.caption.39}{}}

ewlabel{sec:appendix_partial_corr}{{E.1}{15}{Partial Correlation: Controlling for Degree Centrality}{subsection.E.1}{}}

ewlabel{tab:partial_corr}{{12}{16}{BCS--accuracy partial correlation controlling for degree centrality. FewRel shows minimal attenuation (VIF${}\,=\,1.18$, low collinearity). DocRED shows high BCS--centrality collinearity (VIF${}\,=\,50.9$, $r = 0.99$), but the partial correlation remains highly significant}{table.caption.41}{}}

ewlabel{sec:appendix_ner_power}{{E.2}{16}{NER BCS-Null Power Analysis}{subsection.E.2}{}}

ewlabel{sec:appendix_bootstrap_ci}{{E.3}{16}{Bootstrap CI Robustness}{subsection.E.3}{}}

ewlabel{sec:appendix_domain_distribution}{{E.4}{16}{Domain Distribution in Extreme-BCS Batches}{subsection.E.4}{}}

ewlabel{sec:appendix_batch_composition}{{F}{17}{Batch Composition Results}{appendix.F}{}}

ewlabel{tab:batch_composition}{{13}{17}{Batch composition on FewRel 80-relation RE with oracle routing. $^\dagger $Mean $\pm $ SD across 15 random seeds}{table.caption.43}{}}

ewlabel{sec:appendix_prompts}{{G}{17}{Prompt Templates}{appendix.G}{}}

ewlabel{sec:appendix_type_defs}{{G.4}{18}{Type Definitions}{subsection.G.4}{}}

ewlabel{sec:appendix_prompt_sensitivity}{{H}{18}{Prompt Version Sensitivity Analysis}{appendix.H}{}}

ewlabel{sec:appendix_prompt_variants}{{H.1}{19}{Cross-Prompt-Variant BCS Correlation}{subsection.H.1}{}}

ewlabel{tab:prompt_variants}{{14}{19}{BCS--accuracy Pearson correlation across four prompt variants. At count 32, all four variants show negative BCS--accuracy correlations ($r \leq -0.47$), with two reaching $p < 0.05$. At count 8, the narrower BCS range reduces statistical power}{table.caption.54}{}}

ewlabel{sec:appendix_bcs_sensitivity}{{I}{19}{BCS Aggregation Sensitivity}{appendix.I}{}}

ewlabel{tab:bcs_aggregation}{{15}{19}{BCS--accuracy regression under mean vs.\ max pairwise SCS aggregation (FewRel, 16-relation batches). Permutation test for slope equivalence across pools: MEAN $p \approx 0.60$; MAX $p \approx 0.44$. The 80-pool row is identical under both definitions because these batches were collected using mean-aggregated BCS; the MAX column reflects the same data for completeness}{table.caption.55}{}}

ewlabel{app:bcs-controlled-table}{{J}{19}{BCS-Controlled Detailed Results}{appendix.J}{}}

ewlabel{tab:bcs_controlled}{{16}{20}{BCS-controlled FewRel accuracy. Low-BCS batches contain maximally dissimilar types; high-BCS batches contain maximally similar types. The 80-relation extreme-batch gap reflects the wider BCS range; regression slopes are consistent across pools ($p = 0.60$; Table~ef {tab:within_pool}; see \S ef {sec:practical_magnitude} for typical-batch magnitudes). The 16-relation condition used a single extreme batch per BCS level; bootstrap CIs require multiple batches}{table.caption.56}{}}

ewlabel{app:format-independence}{{K}{20}{Format Independence: Paired Constrained vs.\ Unconstrained Comparison}{appendix.K}{}}

ewlabel{tab:format_independence}{{17}{20}{Paired comparison of constrained vs.\ unconstrained decoding on 25 identical FewRel batch type sets. Both formats yield virtually identical BCS--accuracy correlations (Fisher $z \approx 0$), confirming the confusability effect is format-independent. Mean accuracy is also unchanged ($\Delta = -0.08$\,pp), ruling out a format-driven accuracy shift}{table.caption.58}{}}

ewlabel{tab:format_perbatch}{{18}{20}{Per-batch accuracy (\%) under constrained and unconstrained decoding on 25 identical FewRel batch type sets (count 8, 96 instances each). 23/25 batches yield identical accuracy; the two exceptions differ by exactly one sample ($\Delta = -1.04$\,pp). L = low-BCS, H = high-BCS}{table.caption.60}{}}

ewlabel{app:within-pool-method}{{L}{20}{Within-Pool Analysis Methodology}{appendix.L}{}}

ewlabel{tab:within_pool}{{19}{21}{Three-way BCS--accuracy analysis on FewRel. Slope: OLS of batch accuracy on BCS (bootstrap CIs, $B{=}10{,}000$). $\Delta $: accuracy gap between top- and bottom-quartile BCS batches. See Appendix~ef {sec:appendix_within_pool} for CI interpretation}{table.caption.61}{}}

ewlabel{app:scs-ablation}{{M}{21}{SCS Embedding Ablation: Name-Only vs. Name+Definition}{appendix.M}{}}

ewlabel{tab:scs-ablation}{{20}{21}{Pearson correlation between SCS and empirical confusion rate. ``Def'' concatenates type name with definition before embedding. All correlations significant ($p < 0.001$). The inconsistent direction of $\Delta r$ indicates that definitions provide no systematic benefit}{table.caption.62}{}}

ewlabel{app:scs-heldout-validation}{{M}{21}{Held-out validation}{section*.63}{}}

ewlabel{app:aggregation-sim}{{N}{21}{Pair-to-Batch Aggregation Simulation}{appendix.N}{}}

ewlabel{app:bcs-composition}{{O}{22}{BCS Independence from Type Composition}{appendix.O}{}}

ewlabel{app:scs-baselines}{{P}{22}{SCS vs.\ Simple Baselines}{appendix.P}{}}

ewlabel{tab:scs_baselines}{{21}{22}{Pairwise confusion prediction: SCS vs.\ simple baselines. Spearman $ho $ between each metric and the empirical confusion rate. SCS outperforms all baselines on FewRel; the margin is smaller on Few-NERD, where hierarchical naming conventions provide partial signal to string-based metrics. $^\dagger $42\% of pairs lack WordNet coverage}{table.caption.69}{}}

ewlabel{app:split-origin}{{Q}{22}{Split-Origin Covariate Analysis}{appendix.Q}{}}

ewlabel{app:variance-decomposition}{{R}{22}{Cross-Seed Variance Decomposition}{appendix.R}{}}

ewlabel{tab:variance_decomposition}{{22}{23}{Variance decomposition on FewRel (3 seeds $	imes $ 25 batches per count level). Batch SD: root-mean intra-seed variance averaged over seeds. Seed SD: standard deviation of per-seed means. Ratio = batch variance / seed variance. At count 80, only one batch composition exists, so batch variance vanishes by construction}{table.caption.72}{}}

ewlabel{app:cross-domain}{{S}{23}{Cross-Domain Connections}{appendix.S}{}}

ewlabel{sec:appendix_cross_model_70b}{{T}{23}{Cross-Model Validation with LLaMA-3.1-70B-Instruct (FP8)}{appendix.T}{}}

ewlabel{tab:cross_model_70b}{{23}{23}{Cross-model count curves for LLaMA-3.1-70B-Instruct (FP8) and Qwen3-32B. RE decline (count 8$	o $80): $-$30.7\,pp (70B) vs.\ $-$30.1\,pp (32B). NER decline (count 2$	o $22): $-$7.1\,pp (70B) vs.\ $-$23.6\,pp (32B); both models exhibit a U-shaped rebound at higher counts. 25 batches per count level, same samples and batch compositions across models (seed 42). All metrics are micro-averaged across batches}{table.caption.73}{}}

ewlabel{sec:appendix_cross_model_gemini}{{U}{24}{Cross-Model Validation with Gemini 2.5 Flash (API)}{appendix.U}{}}

ewlabel{tab:cross_model_gemini}{{24}{24}{Cross-model count curves for Gemini 2.5 Flash (API) and Qwen3-32B on FewRel RE (classification accuracy). 25 batches per count level, same samples and batch compositions (seed 42). Gemini's count-1 result is included for completeness; Qwen3 count-1 was not collected. Both models show monotonic decline from count 4 onward ($ho = -1.0$ for both on counts 4--32). $^\dagger $Count 64: Gemini based on 11/25 batches (partial)}{table.caption.74}{}}

ewlabel{tab:cross_model_bcs_summary}{{25}{24}{Cross-model BCS-controlled FewRel RE summary. All models show significant low-vs-high BCS accuracy gaps. Gap magnitude varies with model capacity (ceiling compression), but the direction is consistent across open-weight (8B--70B) and proprietary architectures}{table.caption.76}{}}

ewlabel{sec:appendix_fewshot_bcs}{{V}{24}{Few-Shot Prompting and Confusability}{appendix.V}{}}

ewlabel{tab:fewshot_bcs}{{26}{25}{BCS gap under few-shot prompting (FewRel, count 8). Demonstrations improve absolute accuracy on low-BCS batches (+3.3--7.2\,pp over 0-shot) but provide inconsistent benefit on high-BCS batches (+5.6\,pp at 1-shot, $-$1.0\,pp at 5-shot). The confusability gap widens from +18.5\,pp (0-shot) to +22.8\,pp (5-shot). All metrics are micro-averaged across batches}{table.caption.77}{}}

ewlabel{app:error-analysis}{{W}{25}{Qualitative Error Analysis}{appendix.W}{}}

ewlabel{app:renaming}{{X}{25}{Schema Label Renaming Experiment}{appendix.X}{}}

